var t=[{title:`Az alapvető futóhelyzet`,text:`Fuss magasan és lazán, a teljes testtel enyhe természetes előredőléssel, a karjaid könnyedén lendüljenek. Tartsd lazán a válladat, és ne nyúlj messzire előre minden lépésnél. A lépésednek összehangoltnak kell érződnie a választott sebességnél, anélkül hogy rögzített sablonba erőltetnéd.`},{title:`Lépésszám és talajfogás`,text:`A lépésszám a percenként megtett lépések száma. Egyes futók számára hasznos lehet kissé változtatni rajta, de nincs szabály arra, hogy mindenkinek percenként 180 lépéssel kellene futnia. A sarok-, a középláb- és az elülső lábfejes talajfogás másképp osztja el az erőket, és a bizonyítékok nem támasztják alá, hogy minden egészséges futót egy landolási mintára kellene átállítani.`},{title:`Séta-futás intervallumok`,text:`Kezdőként váltogathatsz egy perc könnyű kocogást két perc sétával 15–20 percen át, plusz bemelegítéssel és levezetéssel. Több hét alatt hosszabbítsd a kocogó szakaszokat. Idő, magabiztosság és az érzett nehézség szerint építkezz, és tarts sétaszüneteket, valahányszor szeretnél. A megfelelő kezdő mennyiség attól függ, mennyire voltál aktív, hogyan viseli a tested, és milyen a felület, ezért nincs mindenkire érvényes fix beosztás.`},{title:`A sprint külön készség`,text:`A gyors gyorsítások sokkal nagyobb igénybevételt jelentenek az izmoknak és az ínaknak. Építs alap futóerőnlétet, mielőtt teljes sebességgel sprintelsz, és hosszabban melegíts be, amikor gyorsabb erőfeszítéseket adsz hozzá. Állj meg, ha éles vagy egyre rosszabbodó fájdalmat érzel. Olyan cipőt és útvonalat válassz, amely illik a felülethez és a körülményekhez, és ha a futás ütközik az ütésterhelési korlátaiddal, vagy nincs biztonságos útvonalad, végezz alacsony ütésterhelésű állóképességi edzést.`}];var l=[{label:`Szisztematikus áttekintés: a talajfogás technikája és a sérülésveszély`,url:`https://pubmed.ncbi.nlm.nih.gov/34527750/`},{label:`A futási lépésszám és a sérülésveszély szisztematikus áttekintése`,url:`https://pubmed.ncbi.nlm.nih.gov/40964543/`},{label:`CDC: felnőttek fizikai aktivitási ajánlásai`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var a={sections:t,sources:l};export{a as default,t as sections,l as sources};